(assert (= "1.12.6" (clojure-version)))
(def eval-do-effects (atom [])) (def eval-do-root 99)
(defmacro eval-do-top-macro [] '(do (swap! user/eval-do-effects conj :macro) eval-do-missing))
(defmacro eval-do-init-counter [] (do (def eval-do-expansions (atom 0)) nil))
(defmacro eval-do-once [] (swap! eval-do-expansions inc) '(do :one :two))
(defmacro eval-do-read-counter [] @eval-do-expansions)
(defmacro eval-do-reentrant [] (def eval-do-own-effects (atom [])) (let [result (try (eval '(do (swap! user/eval-do-own-effects conj :inside) eval-do-missing)) (catch Throwable e :compile))] [result @eval-do-own-effects]))
(eval-do-init-counter)
(println (pr-str (pr-str (eval '(do)))))
(println (pr-str (pr-str (eval '(do 1N 1/2)))))
(println (pr-str (pr-str (let [_ (reset! eval-do-effects []) result (try (eval '(do (swap! user/eval-do-effects conj :prefix) eval-do-missing)) (catch Throwable e :compile))] [result @eval-do-effects]))))
(println (pr-str (pr-str (let [_ (reset! eval-do-effects []) result (try (eval '(eval-do-top-macro)) (catch Throwable e :compile))] [result @eval-do-effects]))))
(println (pr-str (pr-str (let [_ (reset! eval-do-effects []) result (try (eval '(do (swap! user/eval-do-effects conj :outer) (do (swap! user/eval-do-effects conj :inner) eval-do-missing))) (catch Throwable e :compile))] [result @eval-do-effects]))))
(println (pr-str (pr-str (let [_ (reset! eval-do-effects []) result (try (eval '(let [x (swap! user/eval-do-effects conj :lexical)] eval-do-missing)) (catch Throwable e :compile))] [result @eval-do-effects]))))
(println (pr-str (pr-str (let [_ (reset! eval-do-effects []) result (try (eval '(do (swap! user/eval-do-effects conj :before) (throw (ex-info "stop" {})) (swap! user/eval-do-effects conj :after))) (catch Throwable e :throw))] [result @eval-do-effects]))))
(println (pr-str (pr-str (let [result (try (eval '(do (def eval-do-created 29) eval-do-missing)) (catch Throwable e :compile))] [result (eval 'user/eval-do-created)]))))
(println (pr-str (pr-str (let [_ (reset! eval-do-effects []) result (try (eval '(do (swap! user/eval-do-effects conj :prefix) (def eval-do-root (throw (ex-info "stop" {}))) (swap! user/eval-do-effects conj :after))) (catch Throwable e :throw))] [result @eval-do-effects eval-do-root]))))
(println (pr-str (pr-str (let [value (eval '(eval-do-once))] [value (eval '(eval-do-read-counter))]))))
(println (pr-str (pr-str (eval-do-reentrant))))
